dtsPropsFor.Button:
variant?: "primary" | "secondary" | "ghost" | "danger" | "seal" | "inferred";
  size?: "dense" | "md" | "comfort";
  /** A square control: a filter, a pagination arrow, a kebab. Needs `aria-label`. */
  iconOnly?: boolean;
  /** Swaps the icon for a spinner and blocks the press. */
  loading?: boolean;
  disabled?: boolean;
  /**
   * Give it an `href` and Button renders a real `<a>` carrying the same
   * chrome — that is how you make a link that looks like a button. Leave it
   * off and you get a `<button>`. Never hand-roll an anchor with button
   * styling, and never wrap a Button in an `<a>`.
   *
   * A blocked link (`disabled` or `loading`) drops its `href` and carries
   * `aria-disabled`, because an anchor has no `disabled`.
   *
   * In the package the props are a discriminated union, so `href` is
   * required on the link branch and `type` is rejected there.
   */
  href?: string;
  /** Link branch only, alongside `href`. */
  target?: string;
  /** Link branch only, alongside `href`. */
  rel?: string;
  /** Button branch only — not valid together with `href`. */
  type?: "button" | "submit" | "reset";
  className?: string;
  id?: string;
  style?: CSSProperties;
  children?: React.ReactNode;
